// The app icon (assets/gitmind.svg in the repo), served as favicons. The PNGs
// are rendered from the SVG; regenerate them if it changes.

export const ICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">
  <title>gitmind</title>
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#3a8f77"/>
      <stop offset="1" stop-color="#1d5446"/>
    </linearGradient>
  </defs>
  <rect width="512" height="512" rx="116" fill="url(#bg)"/>
  <!-- A git commit graph: the main line of memory, with a thought branching off. -->
  <g fill="none" stroke="#fff" stroke-width="38" stroke-linecap="round">
    <path d="M196 150 V362"/>
    <path d="M196 318 C196 240 330 268 330 186"/>
  </g>
  <g fill="#fff">
    <circle cx="196" cy="136" r="46"/>
    <circle cx="196" cy="376" r="46"/>
    <circle cx="330" cy="172" r="46"/>
  </g>
  <g fill="#1d5446">
    <circle cx="196" cy="376" r="18"/>
  </g>
</svg>
`;

const png = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
export const ICON_PNG_32 = png("");
export const ICON_PNG_180 = png("");
export const ICON_PNG_512 = png("");
